1	//! A checker type converted to [`PropType`] from the checker's structured answers: type flags, a union's members, a
2	//! reference's type arguments, a tuple's element flags, an object's properties, index and call signatures, an alias's
3	//! symbol and arguments. The printed type (`typeToString`) names things for display and for the two facts the
4	//! structure does not state (see [`crate::printed`]); no shape is read from it.
5	//!
6	//! The conversion of a type is a function of the type, how deep it sits and which declarations enclose it, never of
7	//! the order the checker was asked in, so the memo can be keyed by the checker's type handle (valid inside one
8	//! snapshot) without making the output depend on query order. Nothing here keys on a type id except that memo: a
9	//! recursion marker is keyed by the declaration (the alias or interface), not the id.
10	//!
11	//! What stays a name instead of an expansion, the named boundary: an object type declared in a dependency
12	//! (`node_modules`) or an interface or class of the TypeScript lib (`Date`, `HTMLElement`, `Promise<T>`), with its type
13	//! arguments; a function type is always expanded, since its parameters are what a reader wants. The lib's type-level
14	//! utilities (`Partial`, `Pick`, `Omit`, `Record`) are evaluated, not named: their result is the type. A dependency's
15	//! union of literals is expanded too, since its members are the values a control offers. What the caps cut is a typed
16	//! [`PropType::Truncated`], never the checker's text standing in as a name.
17	
18	use std::future::Future;
19	use std::hash::{Hash, Hasher};
20	use std::pin::Pin;
21	use std::sync::atomic::{AtomicU64, Ordering};
22	use std::sync::{Arc, Mutex};
23	
24	use caliper_docgen_core::types::semantic::{degraded_type, unresolved_type};
25	use caliper_docgen_core::types::{
26	    BigIntValue, CallSignature, EnumMemberValue, FunctionParam, ObjectField, OpaqueReason, PropType,
27	    SignatureKind as Kind, TemplatePart, TruncationLimit, TupleElement, TupleElementKind, TupleLabel,
28	};
29	use rustc_hash::{FxHashMap, FxHasher};
30	
31	use crate::printed::{Marker, parameter_markers, tuple_labels};
32	use crate::rpc::{
33	    CallError, CompactSymbol, ObjectMembers, Rpc, SignatureInfo, SignatureKind, SymbolInfo, TypeInfo, flag,
34	};
35	
36	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
37	const MAX_DEPTH: u8 = 5;
38	/// The most properties an object type lists at the top (a prop's own type) and below it.
39	const MAX_FIELDS: [usize; 2] = [100, 40];
40	/// The most members a union or intersection lists at the top and below it.
41	const MAX_MEMBERS: [usize; 2] = [500, 120];
42	
43	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
44	
45	/// Where a type sits: how deep, and which declarations (aliases, interfaces) enclose it, outermost first.
46	#[derive(Debug, Clone, Default)]
47	pub(crate) struct Cx {
48	    depth: u8,
49	    enclosing: Arc<Vec<String>>,
50	}
51	
52	impl Cx {
53	    fn deeper(&self) -> Cx {
54	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone() }
55	    }
56	
57	    fn inside(&self, identity: &str) -> Cx {
58	        let mut enclosing = (*self.enclosing).clone();
59	        enclosing.push(identity.to_string());
60	        Cx { depth: self.depth, enclosing: Arc::new(enclosing) }
61	    }
62	
63	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
64	        limits[usize::from(self.depth > 0).min(N - 1)]
65	    }
66	
67	    fn fingerprint(&self) -> u64 {
68	        let mut hasher = FxHasher::default();
69	        self.enclosing.hash(&mut hasher);
70	        hasher.finish()
71	    }
72	}
73	
74	/// What declares a type: the alias it was written through, else its interface or class.
75	#[derive(Debug, Clone)]
76	struct Origin {
77	    name: String,
78	    /// The first declaration's handle: stable for the same declaration whatever order the checker is asked in.
79	    identity: String,
80	    /// The declaring file as the checker keys it (lower-cased path).
81	    file: String,
82	    alias: bool,
83	}
84	
85	impl Origin {
86	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
87	        let declaration = symbol.declarations.first().map(String::as_str);
88	        Origin {
89	            name: symbol.name.clone(),
90	            identity: declaration.map_or_else(|| format!("{}:{alias}", symbol.name), str::to_string),
91	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
92	            alias,
93	        }
94	    }
95	
96	    fn in_dependency(&self) -> bool {
97	        self.file.contains("/node_modules/")
98	    }
99	
100	    fn in_lib(&self) -> bool {
101	        let name = self.file.rsplit('/').next().unwrap_or("");
102	        name.starts_with("lib.") && name.ends_with(".d.ts")
103	    }
104	
105	    fn in_react(&self) -> bool {
106	        self.file.contains("/@types/react/")
107	    }
108	
109	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
110	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
111	    fn is_boundary(&self) -> bool {
112	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
113	        if self.in_lib() { !self.alias } else { self.in_dependency() }
114	    }
115	
116	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
117	    fn react_terminal(&self) -> Option<PropType> {
118	        if !self.in_react() {
119	            return None;
120	        }
121	        match (self.name.as_str(), self.alias) {
122	            ("ReactNode", true) | ("ReactElement" | "Element", false) => Some(PropType::ReactNode),
123	            ("ElementType", true) => Some(PropType::ElementType),
124	            ("CSSProperties", false) => Some(PropType::CssProperties),
125	            _ => None,
126	        }
127	    }
128	}
129	
130	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
131	pub(crate) fn declared_in(declaration: &str) -> &str {
132	    declaration.splitn(3, '.').nth(2).unwrap_or("")
133	}
134	
135	type Memo = Mutex<FxHashMap<(u64, u8, u64), PropType>>;
136	
137	#[derive(Default)]
138	struct State {
139	    /// Conversions by (type handle, depth, enclosing declarations). The handle is valid inside this snapshot only.
140	    memo: Memo,
141	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
142	    printed: Mutex<FxHashMap<u64, String>>,
143	    hits: AtomicU64,
144	    misses: AtomicU64,
145	}
146	
147	#[derive(Clone)]
148	pub(crate) struct Converter {
149	    rpc: Arc<Rpc>,
150	    state: Arc<State>,
151	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
152	    reverse: bool,
153	}
154	
155	impl Converter {
156	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
157	        Self { rpc, state: Arc::new(State::default()), reverse }
158	    }
159	
160	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
161	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
162	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
163	        let order: Box<dyn Iterator<Item = usize> + Send> =
164	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
165	        for index in order {
166	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
167	                *slot = Some(self.convert(info, cx).await?);
168	            }
169	        }
170	        Ok(slots.into_iter().flatten().collect())
171	    }
172	
173	    /// Memo hits and misses so far, for the debug line.
174	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
175	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
176	    }
177	
178	    /// The own types of a component's props, from the top.
179	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
180	        self.convert_all(infos, &Cx::default()).await
181	    }
182	
183	    fn convert<'a>(&'a self, info: &'a TypeInfo, cx: &'a Cx) -> Converted<'a> {
184	        Box::pin(async move {
185	            let key = (info.id, cx.depth, cx.fingerprint());
186	            if let Some(hit) = self.state.memo.lock().ok().and_then(|memo| memo.get(&key).cloned()) {
187	                self.state.hits.fetch_add(1, Ordering::Relaxed);
188	                return Ok(hit);
189	            }
190	            self.state.misses.fetch_add(1, Ordering::Relaxed);
191	            let converted = self.uncached(info, cx).await?;
192	            if let Ok(mut memo) = self.state.memo.lock() {
193	                memo.insert(key, converted.clone());
194	            }
195	            Ok(converted)
196	        })
197	    }
198	
199	    async fn uncached(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
200	        if info.is_error() {
201	            return Ok(unresolved_type(self.display(info.id).await?));
202	        }
203	        if let Some(simple) = simple(info) {
204	            return Ok(simple);
205	        }
206	        let flags = info.flags;
207	        if flags & flag::TYPE_PARAMETER != 0 {
208	            return self.type_parameter(info).await;
209	        }
210	        if flags & (flag::STRING_LITERAL | flag::NUMBER_LITERAL | flag::BIG_INT_LITERAL) != 0 {
211	            return self.literal(info).await;
212	        }
213	        if flags & flag::BOOLEAN_LITERAL != 0 {
214	            return Ok(PropType::BoolLiteral(self.boolean_value(info).await?));
215	        }
216	        if flags & flag::UNIQUE_ES_SYMBOL != 0 {
217	            let name = self.rpc.symbol_of_type(info.id).await?.map(|symbol| symbol.name);
218	            return Ok(match name {
219	                Some(name) => PropType::UniqueSymbol { name: name.into() },
220	                None => named(self.display(info.id).await?, Vec::new()),
221	            });
222	        }
223	        if flags & flag::TEMPLATE_LITERAL != 0 {
224	            return self.template(info, cx).await;
225	        }
226	        // Types the checker could not resolve because a type parameter is still open, and `Uppercase<…>`.
227	        if flags & flag::STRING_MAPPING != 0 {
228	            return Ok(named(self.display(info.id).await?, Vec::new()));
229	        }
230	        if flags & (flag::CONDITIONAL | flag::INDEXED_ACCESS | flag::INDEX | flag::SUBSTITUTION) != 0 {
231	            let text = self.display(info.id).await?;
232	            let reason = if flags & flag::CONDITIONAL != 0 {
233	                OpaqueReason::ConditionalType
234	            } else if flags & flag::INDEXED_ACCESS != 0 {
235	                OpaqueReason::IndexedAccess { expression: text.clone() }
236	            } else {
237	                OpaqueReason::UnsupportedExpression
238	            };
239	            return Ok(degraded_type(text, reason));
240	        }
241	        if flags & flag::UNION != 0 {
242	            return self.union(info, cx).await;
243	        }
244	        if flags & flag::INTERSECTION != 0 {
245	            return self.intersection(info, cx).await;
246	        }
247	        if flags & flag::OBJECT != 0 {
248	            return self.object(info, cx).await;
249	        }
250	        Ok(named(self.display(info.id).await?, Vec::new()))
251	    }
252	
253	    /// How the checker prints the type; only ever a name for display, a truncated type's text, or the source of the two
254	    /// facts in [`crate::printed`].
255	    async fn display(&self, id: u64) -> Result<String, CallError> {
256	        if let Some(text) = self.state.printed.lock().ok().and_then(|printed| printed.get(&id).cloned()) {
257	            return Ok(text);
258	        }
259	        let text = self.rpc.type_to_string(id).await?;
260	        if let Ok(mut printed) = self.state.printed.lock() {
261	            printed.insert(id, text.clone());
262	        }
263	        Ok(text)
264	    }
265	
266	    /// What declares the type, when it has a name of its own: an alias, or an interface, class or instantiation of one.
267	    async fn origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
268	        if let Some(alias) = &info.alias_symbol {
269	            return self.origin_of(alias, true, info.id).await;
270	        }
271	        if info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE | flag::OBJECT_REFERENCE) != 0 {
272	            return self.symbol_origin(info).await;
273	        }
274	        Ok(None)
275	    }
276	
277	    /// The interface or class a type is, whatever alias it was written through.
278	    async fn symbol_origin(&self, info: &TypeInfo) -> Result<Option<Origin>, CallError> {
279	        match &info.symbol {
280	            Some(symbol) => self.origin_of(symbol, false, info.id).await,
281	            None => Ok(None),
282	        }
283	    }
284	
285	    /// The declaration behind a symbol, asked once per symbol however many types refer to it.
286	    async fn origin_of(&self, symbol: &CompactSymbol, alias: bool, type_id: u64) -> Result<Option<Origin>, CallError> {
287	        let key = (alias, symbol.clone());
288	        if let Some(known) = self.state.origins.lock().ok().and_then(|origins| origins.get(&key).cloned()) {
289	            return Ok(known);
290	        }
291	        let found =
292	            if alias { self.rpc.alias_symbol(type_id).await? } else { self.rpc.symbol_of_type(type_id).await? };
293	        // `__type` and `__object` are the checker's names for a type that has none.
294	        let found = found.map(|symbol| Origin::of(&symbol, alias)).filter(|origin| !origin.name.starts_with("__"));
295	        if let Ok(mut origins) = self.state.origins.lock() {
296	            origins.insert(key, found.clone());
297	        }
298	        Ok(found)
299	    }
300	
301	    async fn type_parameter(&self, info: &TypeInfo) -> Result<PropType, CallError> {
302	        if info.is_this_type {
303	            return Ok(named("this".to_string(), Vec::new()));
304	        }
305	        let name = match self.rpc.symbol_of_type(info.id).await? {
306	            Some(symbol) => symbol.name,
307	            None => self.display(info.id).await?,
308	        };
309	        Ok(named(name, Vec::new()))
310	    }
311	
312	    async fn literal(&self, info: &TypeInfo) -> Result<PropType, CallError> {
313	        let flags = info.flags;
314	        let value = info.value.as_ref();
315	        let known = if flags & flag::BIG_INT_LITERAL != 0 {
316	            value.and_then(|value| value.as_str()).and_then(BigIntValue::parse).map(PropType::BigIntLiteral)
317	        } else if flags & flag::STRING_LITERAL != 0 {
318	            value.and_then(|value| value.as_str()).map(|text| PropType::StringLiteral(text.to_string()))
319	        } else {
320	            value.and_then(|value| value.as_f64()).map(PropType::NumberLiteral)
321	        };
322	        let Some(literal) = known else { return Ok(named(self.display(info.id).await?, Vec::new())) };
323	        if flags & flag::ENUM_LITERAL == 0 {
324	            return Ok(literal);
325	        }
326	        // A member of an enum is its value and keeps the enum's name.
327	        let Some(member) = self.rpc.symbol_of_type(info.id).await? else { return Ok(literal) };
328	        let Some(parent) = self.rpc.parent_of_symbol(&member.reference).await? else { return Ok(literal) };
329	        let value = match literal {
330	            PropType::StringLiteral(text) => EnumMemberValue::String(text),
331	            PropType::NumberLiteral(number) => EnumMemberValue::Number(number),
332	            other => return Ok(other),
333	        };
334	        Ok(PropType::EnumMember { enum_name: parent.name.into(), member: member.name.into(), value })
335	    }
336	
337	    /// The beta's responses carry neither `value` nor, in some builds, `intrinsicName` for `true` and `false`.
338	    async fn boolean_value(&self, info: &TypeInfo) -> Result<bool, CallError> {
339	        if let Some(name) = info.intrinsic_name.as_deref() {
340	            return Ok(name == "true");
341	        }
342	        if let Some(value) = info.value.as_ref().and_then(|value| value.as_bool()) {
343	            return Ok(value);
344	        }
345	        Ok(self.display(info.id).await? == "true")
346	    }
347	
348	    async fn template(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
349	        let holes = self.rpc.members(info.id).await?;
350	        let mut types = self.convert_all(&holes, &cx.deeper()).await?.into_iter();
351	        let mut parts = Vec::new();
352	        for text in &info.texts {
353	            if !text.is_empty() {
354	                parts.push(TemplatePart::Text(text.clone()));
355	            }
356	            if let Some(hole) = types.next() {
357	                parts.push(TemplatePart::Type(hole));
358	            }
359	        }
360	        Ok(PropType::TemplateLiteral(parts))
361	    }
362	
363	    /// The cut type for a cap: its declaration's name, else how the checker prints it.
364	    async fn truncated(
365	        &self,
366	        info: &TypeInfo,
367	        origin: Option<&Origin>,
368	        limit: TruncationLimit,
369	    ) -> Result<PropType, CallError> {
370	        let text = match origin {
371	            Some(origin) => origin.name.clone(),
372	            None => self.display(info.id).await?,
373	        };
374	        Ok(PropType::Truncated { text, limit })
375	    }
376	
377	    /// The reference back to a declaration that is being expanded around this type.
378	    async fn recursive(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<PropType, CallError> {
379	        let args = self.type_arguments_of(info, origin, cx).await?;
380	        Ok(PropType::Recursive { name: origin.name.clone().into(), args })
381	    }
382	
383	    /// The type arguments a name carries: an alias's own, or the instantiation's (without the `this` type the checker
384	    /// appends to a class or interface).
385	    async fn type_arguments_of(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<Vec<PropType>, CallError> {
386	        let arguments = if origin.alias {
387	            if info.alias_type_arguments.is_empty() {
388	                Vec::new()
389	            } else {
390	                self.rpc.alias_type_arguments(info.id).await?
391	            }
392	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
393	            let mut arguments = self.rpc.type_arguments(info.id).await?;
394	            while arguments.last().is_some_and(|argument| argument.is_this_type) {
395	                arguments.pop();
396	            }
397	            arguments
398	        } else {
399	            Vec::new()
400	        };
401	        self.convert_all(&arguments, &cx.deeper()).await
402	    }
403	
404	    async fn named_type(&self, info: &TypeInfo, origin: &Origin, cx: &Cx) -> Result<PropType, CallError> {
405	        let args = self.type_arguments_of(info, origin, cx).await?;
406	        Ok(PropType::Named { name: origin.name.clone().into(), args })
407	    }
408	
409	    async fn union(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
410	        let origin = self.origin(info).await?;
411	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
412	            return Ok(terminal);
413	        }
414	        if let Some(origin) = &origin
415	            && cx.enclosing.contains(&origin.identity)
416	        {
417	            return self.recursive(info, origin, cx).await;
418	        }
419	        let members = self.rpc.members(info.id).await?;
420	        let total = members.len();
421	        if total > cx.limit(MAX_MEMBERS) {
422	            return self.truncated(info, origin.as_ref(), TruncationLimit::Members { total: to_u32(total) }).await;
423	        }
424	        if cx.depth >= MAX_DEPTH {
425	            return self.truncated(info, origin.as_ref(), TruncationLimit::Depth).await;
426	        }
427	        let inner = origin.as_ref().map_or_else(|| cx.deeper(), |origin| cx.inside(&origin.identity).deeper());
428	        Ok(union_of(self.convert_all(&members, &inner).await?))
429	    }
430	
431	    async fn intersection(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
432	        let origin = self.origin(info).await?;
433	        if let Some(origin) = &origin {
434	            if cx.enclosing.contains(&origin.identity) {
435	                return self.recursive(info, origin, cx).await;
436	            }
437	            // A dependency's `Nested<Style>`-like alias is a name, as its interface would be.
438	            if origin.is_boundary() {
439	                return self.named_type(info, origin, cx).await;
440	            }
441	        }
442	        let members = self.rpc.members(info.id).await?;
443	        let total = members.len();
444	        if total > cx.limit(MAX_MEMBERS) {
445	            return self.truncated(info, origin.as_ref(), TruncationLimit::Members { total: to_u32(total) }).await;
446	        }
447	        if cx.depth >= MAX_DEPTH {
448	            return self.truncated(info, origin.as_ref(), TruncationLimit::Depth).await;
449	        }
450	        let inner = origin.as_ref().map_or_else(|| cx.deeper(), |origin| cx.inside(&origin.identity).deeper());
451	        let mut converted: Vec<PropType> = Vec::with_capacity(total);
452	        for member in self.convert_all(&members, &inner).await? {
453	            if !converted.contains(&member) {
454	                converted.push(member);
455	            }
456	        }
457	        Ok(if converted.len() == 1 { converted.swap_remove(0) } else { PropType::Intersection(converted) })
458	    }
459	
460	    async fn object(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
461	        if info.is_tuple_type {
462	            return self.tuple(info, cx).await;
463	        }
464	        if info.object_flags & flag::OBJECT_REFERENCE != 0
465	            && let Some(own) = self.symbol_origin(info).await?
466	            && own.in_lib()
467	            && !own.alias
468	            && matches!(own.name.as_str(), "Array" | "ReadonlyArray")
469	        {
470	            return self.array(info, own.name == "ReadonlyArray", cx).await;
471	        }
472	        let origin = self.origin(info).await?;
473	        if let Some(terminal) = origin.as_ref().and_then(Origin::react_terminal) {
474	            return Ok(terminal);
475	        }
476	        let boundary = origin.as_ref().filter(|origin| origin.is_boundary());
477	        // A dependency's interface is a name unless it is callable; its properties are not asked for.
478	        if let Some(origin) = boundary
479	            && self.rpc.signatures(info.id, SignatureKind::Call).await?.is_empty()
480	        {
481	            return self.named_type(info, origin, cx).await;
482	        }
483	        if let Some(origin) = &origin
484	            && cx.enclosing.contains(&origin.identity)
485	        {
486	            return self.recursive(info, origin, cx).await;
487	        }
488	        if cx.depth >= MAX_DEPTH {
489	            return self.truncated(info, origin.as_ref(), TruncationLimit::Depth).await;
490	        }
491	
492	        let ObjectMembers { calls, constructs, properties, indexes } = self.rpc.object_members(info.id).await?;
493	        // A dependency's function with properties of its own (a component, a hook) is a name.
494	        if let Some(origin) = boundary
495	            && !properties.is_empty()
496	        {
497	            return self.named_type(info, origin, cx).await;
498	        }
499	        let total = properties.len() + indexes.len();
500	        if total > cx.limit(MAX_FIELDS) {
501	            return self.truncated(info, origin.as_ref(), TruncationLimit::Members { total: to_u32(total) }).await;
502	        }
503	
504	        let inner = origin.as_ref().map_or_else(|| cx.deeper(), |origin| cx.inside(&origin.identity).deeper());
505	        if let [call] = calls.as_slice()
506	            && constructs.is_empty()
507	            && properties.is_empty()
508	            && indexes.is_empty()
509	        {
510	            return self.function(call, Some(info.id), &inner).await;
511	        }
512	        let fields = self.fields(&properties, &indexes, &inner).await?;
513	        if calls.is_empty() && constructs.is_empty() {
514	            return Ok(PropType::Object(fields));
515	        }
516	        let mut signatures = Vec::with_capacity(calls.len() + constructs.len());
517	        for (kind, group) in [(Kind::Call, &calls), (Kind::Construct, &constructs)] {
518	            for signature in group {
519	                signatures.push(self.call_signature(kind, signature, &inner).await?);
520	            }
521	        }
522	        Ok(PropType::Callable { signatures, fields })
523	    }
524	
525	    async fn array(&self, info: &TypeInfo, readonly: bool, cx: &Cx) -> Result<PropType, CallError> {
526	        let arguments = self.rpc.type_arguments(info.id).await?;
527	        let Some(element) = arguments.first() else {
528	            return Ok(named(self.display(info.id).await?, Vec::new()));
529	        };
530	        let element = PropType::Array(Box::new(self.convert(element, &cx.deeper()).await?));
531	        // `readonly T[]` is `ReadonlyArray<T>`: the same reference through another declaration.
532	        Ok(if readonly { PropType::Readonly(Box::new(element)) } else { element })
533	    }
534	
535	    async fn tuple(&self, info: &TypeInfo, cx: &Cx) -> Result<PropType, CallError> {
536	        let arguments = self.rpc.type_arguments(info.id).await?;
537	        // The reference carries the arguments; the tuple type it instantiates carries how each element is declared.
538	        let target = self.rpc.target_of_type(info.id).await?;
539	        let labels = if target.labeled_element_declarations.is_empty() {
540	            None
541	        } else {
542	            tuple_labels(&self.display(info.id).await?, arguments.len())
543	        };
544	        let element_types = self.convert_all(&arguments, &cx.deeper()).await?;
545	        let mut elements = Vec::with_capacity(arguments.len());
546	        for (index, element_type) in element_types.into_iter().enumerate() {
547	            let element_flags = target.element_flags.get(index).copied().unwrap_or(1);
548	            let kind = if element_flags & flag::ELEMENT_VARIADIC != 0 {
549	                TupleElementKind::Variadic
550	            } else if element_flags & flag::ELEMENT_REST != 0 {
551	                TupleElementKind::Rest
552	            } else if element_flags & flag::ELEMENT_OPTIONAL != 0 {
553	                TupleElementKind::Optional
554	            } else {
555	                TupleElementKind::Required
556	            };
557	            let label = labels.as_ref().and_then(|labels| labels.get(index)).and_then(|label| TupleLabel::new(label));
558	            // An optional element's type argument includes the `undefined` of leaving it out.
559	            let element_type = without_undefined(element_type, kind == TupleElementKind::Optional);
560	            elements.push(TupleElement { element_type, kind, label });
561	        }
562	        let tuple = PropType::Tuple(elements);
563	        Ok(if target.readonly { PropType::Readonly(Box::new(tuple)) } else { tuple })
564	    }
565	
566	    async fn fields(
567	        &self,
568	        properties: &[SymbolInfo],
569	        indexes: &[crate::rpc::IndexInfo],
570	        cx: &Cx,
571	    ) -> Result<Vec<ObjectField>, CallError> {
572	        let references: Vec<_> = properties.iter().map(|property| &property.reference).collect();
573	        let (types, readonly) = if references.is_empty() {
574	            (Vec::new(), Vec::new())
575	        } else {
576	            (self.rpc.types_of_symbols(&references).await?, self.rpc.readonly_symbols(&references).await?)
577	        };
578	        let converted = self.convert_all(&types, cx).await?;
579	        let mut fields = Vec::with_capacity(properties.len() + indexes.len());
580	        for ((property, prop_type), readonly) in properties.iter().zip(converted).zip(readonly) {
581	            let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
582	            let prop_type = without_undefined(prop_type, !required);
583	            let mut field = ObjectField::new(property_name(&property.name), prop_type, required, String::new());
584	            field.readonly = readonly;
585	            fields.push(field);
586	        }
587	        let sides: Vec<TypeInfo> =
588	            indexes.iter().flat_map(|index| [index.key_type.clone(), index.value_type.clone()]).collect();
589	        let mut sides = self.convert_all(&sides, cx).await?.into_iter();
590	        for index in indexes {
591	            let (Some(key), Some(value)) = (sides.next(), sides.next()) else { break };
592	            let mut field = ObjectField::new("key", value, true, String::new());
593	            field.readonly = index.is_readonly;
594	            field.index_key = Some(Box::new(key));
595	            fields.push(field);
596	        }
597	        Ok(fields)
598	    }
599	
600	    async fn function(&self, signature: &SignatureInfo, printed: Option<u64>, cx: &Cx) -> Result<PropType, CallError> {
601	        let (type_params, params, return_type) = self.signature_parts(signature, printed, cx).await?;
602	        Ok(PropType::Function { type_params, params, return_type: Box::new(return_type) })
603	    }
604	
605	    async fn call_signature(&self, kind: Kind, signature: &SignatureInfo, cx: &Cx) -> Result<CallSignature, CallError> {
606	        // The printed type of an overload set is not one parameter list: which parameters are optional is not stated.
607	        let (type_params, params, return_type) = self.signature_parts(signature, None, cx).await?;
608	        Ok(CallSignature { kind, type_params, params, return_type })
609	    }
610	
611	    async fn signature_parts(
612	        &self,
613	        signature: &SignatureInfo,
614	        printed: Option<u64>,
615	        cx: &Cx,
616	    ) -> Result<(Vec<String>, Vec<FunctionParam>, PropType), CallError> {
617	        let parameters = self.rpc.parameters(signature.id).await?;
618	        let references: Vec<_> = parameters.iter().map(|parameter| &parameter.reference).collect();
619	        let types = if references.is_empty() { Vec::new() } else { self.rpc.types_of_symbols(&references).await? };
620	        // The printed type of the function states which parameters are optional; it is only asked for when there is one.
621	        let markers: Option<Vec<Marker>> = match printed {
622	            Some(id) if !parameters.is_empty() => parameter_markers(&self.display(id).await?),
623	            _ => None,
624	        };
625	        // A printed signature that does not parse into one entry per parameter leaves the markers off.
626	        let markers = markers.filter(|markers| markers.len() == parameters.len());
627	        let has_rest = signature.flags & flag::SIGNATURE_HAS_REST_PARAMETER != 0;
628	        let converted = self.convert_all(&types, cx).await?;
629	        let mut params = Vec::with_capacity(parameters.len());
630	        for (index, (parameter, param_type)) in parameters.iter().zip(converted).enumerate() {
631	            let marker = markers.as_ref().and_then(|markers| markers.get(index)).copied().unwrap_or_default();
632	            let rest = marker.rest || (has_rest && index + 1 == parameters.len());
633	            let optional = marker.optional && !rest;
634	            let param_type = without_undefined(param_type, optional);
635	            // A destructured parameter has no name of its own; the checker calls it `__0`.
636	            let name = (!is_destructured(&parameter.name)).then(|| parameter.name.clone());
637	            params.push(FunctionParam { name, param_type, optional, rest });
638	        }
639	        let return_info = self.rpc.return_type(signature.id).await?;
640	        let return_type = self.convert(&return_info, cx).await?;
641	        let mut type_params = Vec::new();
642	        if !signature.type_parameters.is_empty() {
643	            for parameter in self.rpc.type_parameters(signature.id).await? {
644	                match self.rpc.symbol_of_type(parameter.id).await? {
645	                    Some(symbol) => type_params.push(symbol.name),
646	                    None => type_params.push(self.display(parameter.id).await?),
647	                }
648	            }
649	        }
650	        Ok((type_params, params, return_type))
651	    }
652	}
653	
654	/// The checker keys a property named by a symbol `__@<name>@<symbol id>`; the source writes `[Symbol.iterator]` or
655	/// `[brand]`. The id is the checker's and does not belong in an answer.
656	fn property_name(name: &str) -> String {
657	    const WELL_KNOWN: [&str; 15] = [
658	        "iterator",
659	        "asyncIterator",
660	        "hasInstance",
661	        "isConcatSpreadable",
662	        "match",
663	        "matchAll",
664	        "replace",
665	        "search",
666	        "species",
667	        "split",
668	        "toPrimitive",
669	        "toStringTag",
670	        "unscopables",
671	        "dispose",
672	        "asyncDispose",
673	    ];
674	    let Some((symbol, _id)) = name.strip_prefix("__@").and_then(|rest| rest.rsplit_once('@')) else {
675	        return name.to_string();
676	    };
677	    if WELL_KNOWN.contains(&symbol) { format!("[Symbol.{symbol}]") } else { format!("[{symbol}]") }
678	}
679	
680	fn is_destructured(name: &str) -> bool {
681	    name.strip_prefix("__").is_some_and(|rest| !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit()))
682	}
683	
684	fn to_u32(count: usize) -> u32 {
685	    u32::try_from(count).unwrap_or(u32::MAX)
686	}
687	
688	fn named(name: String, args: Vec<PropType>) -> PropType {
689	    PropType::Named { name: name.into(), args }
690	}
691	
692	/// The types whose conversion needs nothing but their flags.
693	fn simple(info: &TypeInfo) -> Option<PropType> {
694	    let flags = info.flags;
695	    // `boolean` is the union `false | true` and carries both flags.
696	    if flags & flag::BOOLEAN != 0 {
697	        return Some(PropType::Boolean);
698	    }
699	    let known = [
700	        (flag::ANY, PropType::Any),
701	        (flag::UNKNOWN, PropType::Unknown),
702	        (flag::UNDEFINED, PropType::Undefined),
703	        (flag::NULL, PropType::Null),
704	        (flag::VOID, PropType::Void),
705	        (flag::NEVER, PropType::Never),
706	        (flag::STRING, PropType::String),
707	        (flag::NUMBER, PropType::Number),
708	        (flag::BIG_INT, named("bigint".to_string(), Vec::new())),
709	        (flag::ES_SYMBOL, named("symbol".to_string(), Vec::new())),
710	        (flag::NON_PRIMITIVE, named("object".to_string(), Vec::new())),
711	    ];
712	    known.into_iter().find(|(bit, _)| flags & bit != 0).map(|(_, converted)| converted)
713	}
714	
715	/// A union of converted members: `false | true` is `boolean`, a union inside a union is flattened, a repeated member
716	/// is kept once, and a union of one is that member.
717	fn union_of(converted: Vec<PropType>) -> PropType {
718	    let mut flat = Vec::with_capacity(converted.len());
719	    for member in converted {
720	        match member {
721	            PropType::Union(inner) => flat.extend(inner),
722	            other => flat.push(other),
723	        }
724	    }
725	    let both_booleans = flat.contains(&PropType::BoolLiteral(true)) && flat.contains(&PropType::BoolLiteral(false));
726	    let mut members: Vec<PropType> = Vec::with_capacity(flat.len());
727	    for member in flat {
728	        let member = match member {
729	            PropType::BoolLiteral(_) if both_booleans => PropType::Boolean,
730	            other => other,
731	        };
732	        if !members.contains(&member) {
733	            members.push(member);
734	        }
735	    }
736	    if members.len() == 1 { members.swap_remove(0) } else { PropType::Union(members) }
737	}
738	
739	/// An optional prop's type includes `undefined`; react-docgen-typescript drops it, as does the structural result.
740	pub(crate) fn without_undefined(prop_type: PropType, optional: bool) -> PropType {
741	    match prop_type {
742	        PropType::Union(members) if optional => {
743	            let mut kept: Vec<PropType> = members.into_iter().filter(|m| *m != PropType::Undefined).collect();
744	            if kept.len() == 1 { kept.swap_remove(0) } else { PropType::Union(kept) }
745	        }
746	        other => other,
747	    }
748	}
749

