1	//! What the checker prints is where two facts live that its structured answers do not state: whether a parameter is
2	//! optional (`name?: T`), and what a tuple element is labeled (`head: string`). Both are node-level facts that the API
3	//! reaches only through a declaration handle, which names a node by its index in the source file and so cannot be
4	//! read without decoding that file. The readers here take them out of the printed type, and refuse any text that does
5	//! not read to its end (a long type is cut short with `...`), so a fact is missing rather than invented.
6	
7	/// How the checker prints one parameter of a function type: `name?: T` is optional, `...name: T[]` is the rest
8	/// parameter.
9	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
10	pub(crate) struct Marker {
11	    pub optional: bool,
12	    pub rest: bool,
13	}
14	
15	/// The markers of the parameters of a function type as the checker prints it, `(percent?: number, ...rest: string[])
16	/// => string`, one per parameter in order. `None` when the text is not a parameter list that can be read to its end
17	/// (a long type is cut short with `...`).
18	pub(crate) fn parameter_markers(text: &str) -> Option<Vec<Marker>> {
19	    let chars: Vec<char> = text.chars().collect();
20	    // Type parameters come first: `<T>(value: T) => T`.
21	    let open = if chars.first() == Some(&'<') { matching_close(&chars, 0)? + 1 } else { 0 };
22	    if chars.get(open) != Some(&'(') {
23	        return None;
24	    }
25	    let close = matching_close(&chars, open)?;
26	    let list = chars.get(open + 1..close)?;
27	    if list.iter().all(|c| c.is_whitespace()) {
28	        return Some(Vec::new());
29	    }
30	    top_level_segments(list)?.into_iter().map(parameter_marker).collect()
31	}
32	
33	fn parameter_marker(parameter: &[char]) -> Option<Marker> {
34	    let text: String = parameter.iter().collect();
35	    let text = text.trim_start();
36	    let (rest, text) = match text.strip_prefix("...") {
37	        Some(after) => (true, after),
38	        None => (false, text),
39	    };
40	    // The name: an identifier, or `__0` for a destructured parameter. Whatever follows it, `?` marks it optional.
41	    let after_name = text.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_' || c == '$');
42	    if after_name.len() == text.len() {
43	        return None;
44	    }
45	    Some(Marker { optional: after_name.starts_with('?'), rest })
46	}
47	
48	/// The labels of a tuple type as the checker prints it, `[x: number, y?: string]`, one per element in order. `None`
49	/// when the text is not a tuple that can be read to its end, or does not have `count` elements.
50	pub(crate) fn tuple_labels(text: &str, count: usize) -> Option<Vec<String>> {
51	    let text = text.trim();
52	    let text = text.strip_prefix("readonly ").unwrap_or(text);
53	    let chars: Vec<char> = text.chars().collect();
54	    if chars.first() != Some(&'[') || matching_close(&chars, 0)? + 1 != chars.len() {
55	        return None;
56	    }
57	    let list = chars.get(1..chars.len() - 1)?;
58	    let labels: Vec<String> = top_level_segments(list)?.into_iter().map(tuple_label).collect::<Option<_>>()?;
59	    (labels.len() == count).then_some(labels)
60	}
61	
62	fn tuple_label(element: &[char]) -> Option<String> {
63	    let text: String = element.iter().collect();
64	    let text = text.trim_start();
65	    let text = text.strip_prefix("...").unwrap_or(text);
66	    let name_len = text.find(|c: char| !(c.is_alphanumeric() || c == '_' || c == '$'))?;
67	    let (name, after) = text.split_at(name_len);
68	    // `name: T` and `name?: T`; a bare `T?` is an unlabeled optional element.
69	    let after = after.strip_prefix('?').unwrap_or(after);
70	    (!name.is_empty() && after.starts_with(':')).then(|| name.to_string())
71	}
72	
73	/// The parts of a parameter list between its top-level commas.
74	fn top_level_segments(list: &[char]) -> Option<Vec<&[char]>> {
75	    let mut segments = Vec::new();
76	    let (mut start, mut i) = (0, 0);
77	    while i < list.len() {
78	        match list.get(i)? {
79	            '"' | '\'' | '`' => i = skip_string(list, i)?,
80	            '(' | '[' | '{' | '<' => i = matching_close(list, i)?,
81	            '=' if list.get(i + 1) == Some(&'>') => i += 1,
82	            ',' => {
83	                segments.push(list.get(start..i)?);
84	                start = i + 1;
85	            }
86	            _ => {}
87	        }
88	        i += 1;
89	    }
90	    segments.push(list.get(start..)?);
91	    Some(segments)
92	}
93	
94	/// The index of the bracket that closes the one at `open`, skipping strings and the `>` of `=>`.
95	fn matching_close(chars: &[char], open: usize) -> Option<usize> {
96	    let mut depth = 0usize;
97	    let mut i = open;
98	    while i < chars.len() {
99	        match chars.get(i)? {
100	            '"' | '\'' | '`' => i = skip_string(chars, i)?,
101	            '=' if chars.get(i + 1) == Some(&'>') => i += 1,
102	            '(' | '[' | '{' | '<' => depth += 1,
103	            ')' | ']' | '}' | '>' => {
104	                depth = depth.checked_sub(1)?;
105	                if depth == 0 {
106	                    return Some(i);
107	                }
108	            }
109	            _ => {}
110	        }
111	        i += 1;
112	    }
113	    None
114	}
115	
116	/// The index of the quote that closes the string, or template literal, that starts at `open`.
117	fn skip_string(chars: &[char], open: usize) -> Option<usize> {
118	    let quote = *chars.get(open)?;
119	    let mut i = open + 1;
120	    while i < chars.len() {
121	        match chars.get(i)? {
122	            '\\' => i += 1,
123	            c if *c == quote => return Some(i),
124	            '$' if quote == '`' && chars.get(i + 1) == Some(&'{') => i = matching_close(chars, i + 1)?,
125	            _ => {}
126	        }
127	        i += 1;
128	    }
129	    None
130	}
131	
132	#[cfg(test)]
133	mod tests {
134	    use super::*;
135	
136	    const REQUIRED: Marker = Marker { optional: false, rest: false };
137	    const OPTIONAL: Marker = Marker { optional: true, rest: false };
138	    const REST: Marker = Marker { optional: false, rest: true };
139	
140	    #[test]
141	    fn a_printed_signature_gives_one_marker_per_parameter() {
142	        let cases: [(&str, Vec<Marker>); 6] = [
143	            ("() => void", vec![]),
144	            ("(a: number) => void", vec![REQUIRED]),
145	            ("(percent?: number, ...rest: string[]) => string", vec![OPTIONAL, REST]),
146	            ("(...args: any[]) => void", vec![REST]),
147	            ("(a: number, b?: string) => void", vec![REQUIRED, OPTIONAL]),
148	            // `undefined` in the type is not the `?` marker.
149	            ("(a: number, b: string | undefined) => void", vec![REQUIRED, REQUIRED]),
150	        ];
151	        for (text, expected) in cases {
152	            assert_eq!(parameter_markers(text), Some(expected), "{text}");
153	        }
154	    }
155	
156	    #[test]
157	    fn markers_inside_a_parameter_type_are_not_the_parameters() {
158	        let cases: [(&str, Vec<Marker>); 5] = [
159	            ("(handler: (a?: number, ...b: string[]) => void, c?: string) => void", vec![REQUIRED, OPTIONAL]),
160	            ("(options: { a?: number; b: string }, c?: boolean) => void", vec![REQUIRED, OPTIONAL]),
161	            ("(pair: [first?: string, second?: number], ...more: Array<string>) => void", vec![REQUIRED, REST]),
162	            // Commas and brackets inside a string literal or a template literal type.
163	            ("(key: \"a,b\" | 'c)', template?: `--${string}`) => void", vec![REQUIRED, OPTIONAL]),
164	            ("(map: Map<string, Array<number>>, last?: number) => void", vec![REQUIRED, OPTIONAL]),
165	        ];
166	        for (text, expected) in cases {
167	            assert_eq!(parameter_markers(text), Some(expected), "{text}");
168	        }
169	    }
170	
171	    #[test]
172	    fn type_parameters_and_destructured_parameters_are_skipped_over() {
173	        assert_eq!(parameter_markers("<T>(value: T, key?: keyof T) => T"), Some(vec![REQUIRED, OPTIONAL]));
174	        assert_eq!(parameter_markers("<T extends { a?: 1 }, U = (x?: 1) => 2>(v: T) => U"), Some(vec![REQUIRED]));
175	        assert_eq!(parameter_markers("(__0: { a: string }, __1?: number) => void"), Some(vec![REQUIRED, OPTIONAL]));
176	    }
177	
178	    #[test]
179	    fn text_that_is_not_a_complete_parameter_list_has_no_markers() {
180	        for text in
181	            ["(a: number, b?: Very.Long.Type<With, Many...", "{ a: number }", "", "(a: number", "new (a?: 1) => X"]
182	        {
183	            assert_eq!(parameter_markers(text), None, "{text:?}");
184	        }
185	    }
186	
187	    #[test]
188	    fn a_labeled_tuple_gives_one_label_per_element() {
189	        assert_eq!(tuple_labels("[x: number, y: string]", 2), Some(vec!["x".to_string(), "y".to_string()]));
190	        assert_eq!(
191	            tuple_labels("readonly [head: string, tail?: number, ...rest: boolean[]]", 3),
192	            Some(vec!["head".to_string(), "tail".to_string(), "rest".to_string()])
193	        );
194	        // A comma inside a label's type is not a separator.
195	        assert_eq!(
196	            tuple_labels("[pair: [a: 1, b: 2], map: Map<string, number>]", 2),
197	            Some(vec!["pair".to_string(), "map".to_string()])
198	        );
199	    }
200	
201	    #[test]
202	    fn text_that_is_not_a_labeled_tuple_has_no_labels() {
203	        for (text, count) in [
204	            ("[string, number]", 2),
205	            ("[x: number, string]", 2),
206	            ("[string, number?]", 2),
207	            ("[x: number, y: string]", 3),
208	            ("[x: number, y: Very.Long...", 2),
209	            ("number[]", 1),
210	        ] {
211	            assert_eq!(tuple_labels(text, count), None, "{text}");
212	        }
213	    }
214	}
