1	#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::print_stderr)]
2	//! The checker path over a fixture project of hand-written cases (`tests/fixtures/cases`): the 14 of the checker-first
3	//! deep dive in `Cases.tsx`, and one component per further mapping rule in `Rules.tsx`. The answer is held to a JSON
4	//! snapshot made from a real `tsrs` (`tests/snapshots/`), three ways:
5	//!
6	//! - replayed from its recording (`cases.recording.json`), always: the converter's output over exactly the answers the
7	//!   real checker gave, with no binary;
8	//! - against a real `tsrs` when `TSRS_BIN` names one, which also holds the answer to be the same when the checker is
9	//!   asked last to first (type handles change with the order of queries; the answer may not);
10	//! - merged over the structural result, which puts a union's members back in the order they were written in.
11	//!
12	//! Refresh the recording and the snapshot with `cargo run -p caliper-docgen-semantic --example record_fixture --
13	//! $TSRS_BIN cases`, then `cargo insta review`.
14	
15	use std::time::Duration;
16	
17	use caliper_docgen_core::pipeline::{PipelineOptions, extract};
18	use caliper_docgen_core::types::ExtractionOutput;
19	use caliper_docgen_core::types::semantic::{SemanticOutcome, merge_semantic};
20	use caliper_docgen_semantic::{SemanticRequest, resolve, targets_of};
21	use camino::{Utf8Path, Utf8PathBuf};
22	use serde_json::{Value, json};
23	
24	const FAKE_VERSION: &str = "7.1.0-test";
25	
26	struct Project {
27	    _dir: tempfile::TempDir,
28	    root: Utf8PathBuf,
29	}
30	
31	/// `from` copied to `to`, with a `modules` directory named `node_modules` (which the repository's ignore rules would not
32	/// keep).
33	fn copy_fixture(from: &Utf8Path, to: &Utf8Path) {
34	    for entry in std::fs::read_dir(from).unwrap() {
35	        let entry = entry.unwrap();
36	        let name = entry.file_name().to_str().unwrap().to_string();
37	        let target = to.join(if name == "modules" { "node_modules" } else { &name });
38	        if entry.file_type().unwrap().is_dir() {
39	            std::fs::create_dir_all(&target).unwrap();
40	            copy_fixture(&Utf8PathBuf::from_path_buf(entry.path()).unwrap(), &target);
41	        } else {
42	            std::fs::copy(entry.path(), &target).unwrap();
43	        }
44	    }
45	}
46	
47	/// The cases in a scratch directory whose name has an upper-case letter (see `replay_tsc.rs`), with `replay-tsc`
48	/// installed as `node_modules/typescript/bin/tsc` when `replay`.
49	fn project(replay: bool) -> Project {
50	    let dir = tempfile::Builder::new().prefix("Cases").tempdir().unwrap();
51	    let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
52	    copy_fixture(&Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/cases"), &root);
53	    if replay {
54	        let package = root.join("node_modules/typescript");
55	        std::fs::create_dir_all(package.join("bin")).unwrap();
56	        std::fs::write(package.join("package.json"), format!(r#"{{"version": "{FAKE_VERSION}"}}"#)).unwrap();
57	        std::fs::copy(env!("CARGO_BIN_EXE_replay-tsc"), package.join("bin/tsc")).unwrap();
58	    }
59	    Project { _dir: dir, root }
60	}
61	
62	fn structural(project: &Project) -> ExtractionOutput {
63	    extract(&PipelineOptions { src_dirs: vec![project.root.clone()], ..PipelineOptions::default() })
64	}
65	
66	enum Checker {
67	    Replay,
