71	fn answer(project: &Project, output: &ExtractionOutput, checker: &Checker) -> SemanticOutcome {
72	    let mut request = SemanticRequest::new(project.root.clone(), targets_of(output));
73	    request.request_timeout = Duration::from_secs(60);
74	    match checker {
75	        Checker::Replay => {
76	            request.expected_versions = &[FAKE_VERSION];
77	            request.extra_env.push((
78	                "REPLAY_FIXTURE".to_string(),
79	                format!("{}/tests/fixtures/cases.recording.json", env!("CARGO_MANIFEST_DIR")),
80	            ));
81	        }
82	        Checker::Real { bin, reverse } => {
83	            request.tsc_path = Some(bin.clone());
84	            request.reverse_queries = *reverse;
85	        }
86	    }
87	    resolve(request)
88	}
