90	/// The outcome as the JSON the snapshot holds: each component's props in the order the checker gave them.
91	fn rendered(outcome: &SemanticOutcome) -> Value {
92	    let components: serde_json::Map<String, Value> = outcome
93	        .components
94	        .iter()
95	        .map(|component| {
96	            let props: Vec<Value> = component
97	                .props
98	                .iter()
99	                .map(|prop| {
100	                    json!({
101	                        "name": prop.name,
102	                        "required": prop.required,
103	                        "type": serde_json::to_value(&prop.prop_type).unwrap(),
104	                    })
105	                })
106	                .collect();
107	            (component.display_name.clone(), Value::Array(props))
108	        })
109	        .collect();
110	    let fallbacks: serde_json::Map<String, Value> =
111	        outcome.fallbacks.iter().map(|fallback| (fallback.display_name.clone(), json!(fallback.reason))).collect();
112	    json!({ "components": components, "fallbacks": fallbacks })
113	}
