22	impl std::fmt::Display for CallError {
23	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
24	        match self {
25	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
26	        }
27	    }
