60	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
61	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
62	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
63	/// so are the internal names, which start with exactly two.
64	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
65	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
66	}
