235	/// One `tsc --api` session bound to a snapshot and project.
236	pub(crate) struct Rpc {
237	    client: Client,
238	    deadline: Duration,
239	    snapshot: u64,
240	    project: String,
241	    /// Every call and its answer, when the caller asked to record a replay fixture.
242	    recording: Option<Mutex<Vec<Value>>>,
243	    calls: Mutex<BTreeMap<String, u64>>,
244	}
245	
246	impl Rpc {
247	    pub(crate) async fn open(
248	        client: Client,
249	        deadline: Duration,
250	        tsconfig: Option<&str>,
251	        root_files: &[String],
252	        record: bool,
253	    ) -> Result<Rpc, CallError> {
254	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
255	        Rpc::open_with(client, deadline, &options, root_files, record).await
256	    }
257	
258	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
259	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
260	    /// numeric ones.
261	    pub(crate) async fn prepare(
262	        client: &Client,
263	        deadline: Duration,
264	        tsconfig: Option<&str>,
265	    ) -> Result<Value, CallError> {
266	        let rpc = Rpc {
267	            client: client.clone(),
268	            deadline,
269	            snapshot: 0,
270	            project: String::new(),
271	            recording: None,
272	            calls: Mutex::new(BTreeMap::new()),
273	        };
274	        rpc.call("initialize", Value::Null).await?;
275	        Ok(match tsconfig {
276	            Some(file) => {
277	                let parsed = rpc.call("parseConfigFile", json!({ "file": file })).await?;
278	                parsed.get("options").cloned().unwrap_or_else(default_options)
279	            }
280	            None => default_options(),
281	        })
282	    }
283	
284	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
285	    pub(crate) async fn open_with(
286	        client: Client,
287	        deadline: Duration,
288	        options: &Value,
289	        root_files: &[String],
290	        record: bool,
291	    ) -> Result<Rpc, CallError> {
292	        let mut rpc = Rpc {
293	            client,
294	            deadline,
295	            snapshot: 0,
296	            project: String::new(),
297	            recording: record.then(|| Mutex::new(Vec::new())),
298	            calls: Mutex::new(BTreeMap::new()),
299	        };
300	        let created = rpc
301	            .call(
302	                "createSnapshot",
303	                json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] }),
304	            )
305	            .await?;
306	        let response: SnapshotResponse = decode(created)?;
307	        let project = response
308	            .projects
309	            .into_iter()
310	            .next()
311	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
312	        rpc.snapshot = response.snapshot;
313	        rpc.project = project.id;
314	        Ok(rpc)
315	    }
