321	    /// The recorded calls as a JSON array, or `None` when recording was off.
322	    pub(crate) fn recording(&self) -> Option<Value> {
323	        let log = self.recording.as_ref()?.lock().ok()?;
324	        Some(Value::Array(log.clone()))
325	    }
