327	    /// Requests sent so far, by method.
328	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
329	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
330	    }
331	
332	    async fn call(&self, method: &str, params: Value) -> Result<Value, CallError> {
333	        if let Ok(mut calls) = self.calls.lock() {
334	            *calls.entry(method.to_string()).or_default() += 1;
335	        }
336	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
337	        let answer = self.client.request(method, params.clone(), self.deadline).await.map_err(classify)?;
338	        if let Some(log) = &self.recording
339	            && let Ok(mut log) = log.lock()
340	        {
341	            log.push(json!({ "method": method, "params": params, "result": answer.value }));
342	        }
343	        Ok(answer.value)
344	    }
