346	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
347	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
348	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
349	            base.extend(extra);
350	        }
351	        decode(self.call(method, params).await?)
352	    }
