408	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
409	    /// that may legitimately fail.
410	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Value>, CallError> {
411	        let wanted = requests.len();
412	        let scoped: Vec<Value> = requests
413	            .into_iter()
414	            .map(|(method, mut params)| {
415	                if let Value::Object(map) = &mut params {
416	                    map.insert("snapshot".to_string(), json!(self.snapshot));
417	                    map.insert("project".to_string(), json!(self.project));
418	                }
419	                json!({ "method": method, "params": params })
420	            })
421	            .collect();
422	        let mut answers = Vec::with_capacity(wanted);
423	        let mut token: Option<String> = None;
424	        loop {
425	            let mut params = json!({ "requests": scoped });
426	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
427	                map.insert("continuationToken".to_string(), json!(token));
428	            }
429	            let page: BatchPage = decode(self.call("batchRequests", params).await?)?;
430	            for response in page.responses {
431	                if let Some(error) = response.error {
432	                    return Err(CallError::Rejected(error));
433	                }
434	                answers.push(response.result);
435	            }
436	            match page.continuation_token {
437	                Some(next) => token = Some(next),
438	                None => break,
439	            }
440	        }
441	        if answers.len() != wanted {
442	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
443	        }
444	        Ok(answers)
445	    }
