  union: {{ a: {{ b: {{ c: {{ d: {{ e: 'x' | 'y' }} }} }} }} }};
  intersection: {{ a: {{ b: {{ c: {{ d: {{ e: {{ p: 1 }} & {{ q: 2 }} }} }} }} }} }};
  array: {{ a: {{ b: {{ c: {{ d: {{ e: string[] }} }} }} }} }};
  tuple: {{ a: {{ b: {{ c: {{ d: {{ e: [1, 2] }} }} }} }} }};
  template: {{ a: {{ b: {{ c: {{ d: {{ e: `${{number}}px` }} }} }} }} }};
  scalar: {{ a: {{ b: {{ c: {{ d: {{ e: string }} }} }} }} }};
}}) {{ return null; }}

"""
open(path, "w").write(src[:start] + caps + src[end:])

