def render(t, depth=0):
    k = t.get("kind")
    if k == "object":
        return "{" + ", ".join(f["name"] + ("" if f["required"] else "?") + ": " + render(f["propType"]) for f in t["fields"]) + "}"
    if k == "truncated":
        return "TRUNC(%s, %s)" % (t["text"][:40], json.dumps(t["limit"]))
    if k == "array":
        return render(t["element"]) + "[]"
    if k == "recursive":
        return "REC(%s<%s>)" % (t["name"], ",".join(render(a) for a in t["args"]))
    if k == "tuple":
        return "[" + ", ".join(render(e["type"]) for e in t["elements"][:5]) + "]"
    if k == "readonly":
        return "readonly " + render(t["element"])
    if k == "opaque":
        return "OPAQUE(%s, %s)" % (t.get("raw", "")[:60], json.dumps(t.get("reason")))
    if k == "function":
        return "fn(" + ", ".join(("..." if p.get("rest") else "") + str(p.get("name")) + ("?" if p.get("optional") else "") + ": " + render(p["paramType"]) for p in t["params"]) + ") => " + render(t["returnType"])
    return json.dumps(t)[:120]


for name in sys.argv[1:]:
    print("==", name)
    for p in d["components"][name]:
        print("  ", p["name"], render(p["type"])[:700])

