        let outcome = resolve(request);
        println!(
            "{{\"mode\":\"project\",\"components\":{},\"structuralMs\":{structural_ms:.1},\"projectMs\":{:.1},\"answered\":{},\"props\":{}}}",
            all.len(),
            ms(started.elapsed()),
